window.GOHUD_SEARCH=window.GOHUD_SEARCH||{};
window.GOHUD_SEARCH["id"]={"p":["index.html","install.html","ai.html","widgets.html","widgets-surfaces.html","widgets-messages.html","widgets-hud.html","widgets-feedback.html","widgets-forms.html","widgets-shapes.html","widgets-overlays.html","widgets-style.html","theming.html","theming-presets.html","theming-tokens.html","theming-opacity.html","theming-skins.html","theming-own.html","theming-contrast.html"],"n":["Ringkasan","Instalasi","AI SKILL","Widget","Widgets-Surfaces","Widgets-Messages","Widgets-Hud","Widgets-Feedback","Widgets-Forms","Widgets-Shapes","Widgets-Overlays","Widgets-Style","Tema","Theming-Presets","Theming-Tokens","Theming-Opacity","Theming-Skins","Theming-Own","Theming-Contrast"],"d":[[0,"showcase","Seperti apa tampilannya di dalam game",0,"Preset abad pertengahan dan sci-fi — lembar karakter, inventaris, dan misi; formulir, grid, dan kartu ajakan; panel bersudut dan kontrol sentuh. Mengganti preset cukup satu baris kode. Abad pertengahan — karakter, inventaris, dan misi Abad pertengahan — formulir, grid, dan kartu ajakan Sci-fi — panel bersudut dan kontrol sentuh Keenam preset dan cara menggantinya →","",-1],[0,"what","Apa yang tidak perlu lagi Anda urus",0,"Yang paling menyita waktu di UI game bukanlah bentuk sebuah tombol — melainkan segala hal yang berbeda-beda antarperangkat. gohud mengurus perbedaan itu di satu tempat. Setiap ukuran adalah token Jarak, sudut, dan ukuran teks dipanggil lewat nama, bukan ditulis sebagai angka. Tukar temanya dan seluruh layar ikut berubah. Ukuran terlihat ≠ ukuran yang bisa ditekan Tombol tutup terlihat 36dp tetapi target sentuhnya 48dp. Di tempat slot berdesakan saling tumpang tindih, yang pusatnya lebih dekat yang menerima tekanan. Notch dan keyboard Bagian-bagian HUD duduk di dalam area aman, dan kolom masukan naik ke atas keyboard virtual begitu keyboard muncul. Tombol kembali menutup satu hal Escape dan tombol Back Android menutup hanya permukaan paling atas. Jendela yang bertumpuk tidak lenyap bersamaan. Pemberitahuan tidak pernah merampas input Tekan menembus snackbar dan tombol di bawahnya tetap menerimanya. Fokus pun tidak diambil. Ikon diminta lewat namanya Widget hanya tahu GoIconSet.CLOSE. Tukar setnya dan semua gambar berubah tanpa menyentuh satu baris kode. Enam tampilan, satu baris GoUi.use_preset() menukar tema, skin, dan ikon sekaligus — bingkai membulat, sci-fi bersudut potong, atau tempaan abad pertengahan. Keterbacaan yang terukur Setiap tema diperiksa terhadap WCAG, termasuk keadaan tombol dan panel HUD tembus pandang di atas putih murni dan hitam murni. Semuanya berjalan tanpa mengaktifkan plugin. Mengaktifkannya menambahkan autoload GoRuntime yang melacak ukuran jendela, skala dp, dan tinggi keyboard, ditambah project setting untuk resource konfigurasi dan preset — kemudahan, bukan keharusan.","",-1],[0,"install","Memasang gohud",0,"Dua jalan. Serahkan pada agen AI, atau letakkan foldernya di proyekmu — tidak ada lagi yang perlu diatur. Instalasi","",-1],[0,"start","Mulai cepat",0,"Lima baris menampilkan layar bertema. Langkah lengkapnya ada di halaman pemasangan. Mulai cepat","",-1],[0,"presets","Ubah tampilan — warna dan bentuk",0,"Sebuah Theme hanya bisa mengubah gaya apa yang digambar mesin. Sudut membulat adalah satu-satunya sudut yang dimiliki StyleBoxFlat, sedangkan joystick, slot cepat, dan coach mark digambar oleh kode — jadi tema saja tidak akan pernah bisa mengubah bentuknya. Karena itu gohud menyediakan preset: tema, skin, dan set ikon yang dipilih sebagai satu paket. Preset Tampilan default_dark gohud yang asli — sudut membulat, aksen biru lembut default_light Bentuk yang sama pada palet terang scifi_dark Sudut potong, tepi dan pendar neon sian, joystick heksagonal, kurung penanda sasaran scifi_light Bentuk bersudut yang sama dalam palet cetak biru yang cerah medieval_dark Besi gelap dan kulit, bingkai emas antik, paku keling, ikon ukiran, judul Cinzel medieval_light Perkamen, tinta, dan perunggu dengan bingkai tempaan yang sama default_dark — sudut membulat, aksen biru lembut default_light — bentuk sama, palet terang scifi_dark — sudut potong, neon sian scifi_light — bentuk bersudut sama, palet cetak biru Keempatnya adalah layar galeri yang sama. Tidak ada satu baris kode pun yang berbeda — hanya nama presetnya. Sudut tombol, bentuk sakelar, baris daftar, dan garis tepi kolom masukan semuanya berubah bersamaan.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # tema, skin, dan ikon sekaligus",-1],[0,"medieval-collection","Koleksi abad pertengahan",1,"medieval_dark memadukan besi dan kulit dengan emas antik; medieval_light memakai perkamen dan tinta. Bingkai menu membawa paku keling dan ornamen sudut kecil, sementara HUD yang selalu terlihat tetap tenang; 16 ikon ukiran menggambar ulang nama-nama benda, dan hanya judul serta subjudul yang memakai font Cinzel bawaan. medieval_dark — besi dan kulit medieval_light — perkamen dan tinta Kedua tangkapan layar itu adalah examples/medieval/medieval.tscn, dibangun dari widget standar. Panduan abad pertengahan dan cara membuat kerajaan Anda sendiri →","",4],[0,"the-same-screen-on-a-phone-and-on-a-desktop","Layar yang sama di ponsel dan di desktop",1,"Tangkapan layar galeri itu ponsel dalam mode potret. Di bawah ini kode yang sama pada 1280×800 — kontennya berhenti pada lebar yang nyaman dibaca (480dp) lalu memusat, sementara HUD tetap di sudut-sudut. Formulirnya memutari bagian HUD yang mengambang, tetapi tidak bergeser bila memang sudah tidak bertabrakan: memaksanya bergeser justru akan melempar konten keluar dari pusat pada layar lebar. default_dark · 1280×800 scifi_dark · 1280×800","",4],[0,"the-same-sheet-a-different-look","Lembar yang sama, tampilan yang berbeda",1,"Default — kartu membulat, baris pencarian dan footer yang menempel Sci-fi — tepi aksen di atas, sudut terpotong, pendar Pilih salah satu dari Project Settings → gohud → Theme → Preset, atau setel GoConfig.preset. Mengisi theme, skin, atau icons secara eksplisit mengalahkan preset, sehingga Anda bisa memakai sebuah preset dan menimpa salah satunya saja. Tema baru cukup satu berkas JSON. new_theme.py kingdom --from medieval_dark menulis palet yang menjabarkan setiap nilai warisan; make_theme.py kingdom membangun temanya, gambar kontrolnya, dan kenop skinnya, lalu presetnya muncul di pemilih. Setiap setelan dan kenop →","",4],[0,"skin","Skin — tempat yang tak terjangkau Theme",0,"Sebuah skin memiliki joystick, muka slot cepat, cincin coach mark, chip, kerangka pemuatan, peringatan, pemisah, dan judul bagian. Turunkan kelasnya dan timpa hanya apa yang ingin Anda ubah. Kelas Bentuk yang bisa dibuatnya GoStyleBoxCut Sudut terpotong diagonal (chamfer), satu tepi aksen yang ditebalkan, pendar di luar GoStyleBoxBracket Hanya penanda sudut, tanpa mengurung kontennya GoStyleBoxMedieval Bingkai tempaan dengan paku keling, ukiran sudut, sorotan bevel, dan serat material Ketiganya tersimpan ke dalam resource Theme — dan itulah yang membuat sebuah tema bisa mengubah bentuk, bukan hanya warna. GoSkinSciFi dan GoSkinMedieval adalah subkelas bawaan. GoStyle.box() selalu mengembalikan StyleBoxFlat, karena kode pemanggilnya menerima objek itu lalu menyetel bg_color atau corner_radius. Pakai GoStyle.surface() bila bentuk khusus harus tetap bertahan.","class_name MySkin extends GoSkin func slot_box(accent: Color, lit: bool) -> StyleBox: var box := GoStyleBoxCut.new() box.bg_color = accent box.cut = 6.0 box.edge_color = accent return box",-1],[0,"widgets","Widget",0,"Seluruh bagiannya dalam satu tabel. Rinciannya satu per satu → Kelas Basis Fungsinya GoSurface Control Cangkang kartu mengambang — penempatan di tengah, bawah, atau tertambat, header dan footer yang menempel, body yang bergulir, tarik untuk mengubah ukuran GoSheet CanvasLayer Halaman yang naik dari bawah, pada lapisannya sendiri sehingga selalu berada di atas HUD GoDialogs Node Konfirmasi dan peringatan yang bisa Anda await; destructive untuk tindakan yang tak bisa dibatalkan GoForm MarginContainer Formulir berlebar terbatas yang menghindari keyboard virtual dan, dengan avoid_hud, menghindari HUD GoScroll ScrollContainer Gulir sentuh; bilah gulirnya menyelip ke dalam padding kartu GoNotice PanelContainer Snackbar yang tidak mengambil input maupun fokus GoPromptCard PanelContainer Pertanyaan yang tidak menghentikan jalannya game GoCoachMark Control Tur berpemandu yang menunjuk kontrol sungguhan; menekan sasarannya akan melanjutkan tur GoHudAnchor Control Menyematkan bagian HUD ke salah satu dari sembilan titik area aman GoBar Control Bar darah, mana, dan pengalaman dengan perubahan yang dilandaikan GoSlot Button Satu slot cepat — ikon, jumlah, waktu jeda, dan pintasan pada satu muka GoJoystick Control Stik virtual dalam mode tetap, mengikuti, atau relatif GoIconButton Button Terlihat kecil, ditekan besar GoStyle statis Tombol, baris daftar, kolom masukan, chip, tabel, tab, dan lainnya, dibuat dengan satu cara yang konsisten","",-1],[0,"waiting-telling-counting","Menunggu, memberi tahu, menghitung",1,"Kelas Basis Fungsinya GoSnackbar Node pesan yang menempatkan dirinya sendiri GoSpinner Control menunggu tanpa tahu kapan berakhirnya GoBadge PanelContainer titik belum dibaca, tanda BARU, dan 99+","",9],[0,"forms-and-lists","Formulir dan daftar",1,"Kelas Basis Fungsinya GoField VBoxContainer baris yang bisa salah GoInputGroup HBoxContainer masukan yang dilas ke tombolnya GoCombobox Button pemilih yang bisa mencari GoCodeInput VBoxContainer kode kupon dan hadiah GoTable VBoxContainer kepala kolom yang bisa diurutkan, baris yang bisa dipilih GoPagination HBoxContainer halaman, atau baris Selengkapnya","",9],[0,"shapes-games-actually-use","Bentuk-bentuk yang benar-benar dipakai game",1,"Kelas Basis Fungsinya GoRewardCalendar VBoxContainer absensi harian GoRadar · GoDonut Control statistik dalam sekali lihat GoCarousel VBoxContainer banner dan pemilihan karakter GoKbd HBoxContainer petunjuk tombol yang tidak berbohong","",9],[0,"over-the-screen","Di atas layar",1,"Kelas Basis Fungsinya GoDrawer CanvasLayer panel samping GoPopover RefCounted kartu yang disematkan GoContextMenu RefCounted tekan lama dan klik kanan GoConsole CanvasLayer konsol pengembang","",9],[0,"ai","AI SKILL",0,"gohud membawa AI skill: seluruh API, templat siap jalan, dan peluncur pratinjau. Tempelkan satu blok ke agen codingmu — ia memasang gohud dan tahu cara memakainya. AI SKILL","",-1],[0,"readable","Keterbacaan itu diukur, bukan dikira-kira",0,"\"Cantik\" itu selera; \"terbaca\" itu bisa diukur. Teks abu-abu samar terlihat baik-baik saja di monitor bagus dan lenyap di ponsel saat siang bolong — memilih dengan mata telanjang menjamin hal itu cepat atau lambat terjadi. Setiap pasangan warna dan setiap label keadaan tombol di atas panel tempatnya berada diukur terhadap WCAG, pada keenam tema. Warna tembus pandang lebih dulu dikomposit di atas latar sesungguhnya — mengukurnya secara langsung akan melaporkan rasio yang lebih baik daripada yang tampak di layar. Karena itu warna teks diturunkan, bukan dipilih: pembangun tema mengambil entri palet sebagai titik berangkat lalu mendorong terangnya sampai melewati ambang batas pada setiap permukaan yang mungkin ditempatinya. Ubah paletnya dan kontrasnya ikut menyesuaikan. Aturannya dan jebakan di baliknya → Pemeriksaan, rilis, dan situs ini Satu titik masuk menjalankan semua pemeriksaan; tiap bagian melihat sesuatu yang tak terlihat oleh yang lain. Pemeriksaan Apa yang ditangkapnya run_tests.sh pada empat ukuran layar Perilaku dan tata letak widget, posisi RTL, fokus keyboard, kontras skin saat runtime, semua preset new_project_check.sh Ketergantungan tersembunyi pada proyek induk; dengan --zip menguji rilis apa adanya, dengan --export sebuah build Web check_contrast.py Kontras WCAG setiap berkas tema, termasuk keadaan tombol dan panel tembus pandang check_generated.py · check_scaffold.sh Tema hasil generasi cocok dengan paletnya; tema sekali pakai berhasil dibangun dan lolos uji kontras check_package.py Kenaikan versi, perpindahan changelog, dan isi ZIP, pada salinan sementara check_site.py Tautan, jangkar, bahasa halaman, glosarium, dan tabel kenop situs ini Jalan uji terakhir yang tercatat — 2026-09-13, Godot 4.7.2, macOS, renderer Compatibility. 438 dari 438 pemeriksaan pada 390×844, 844×390, 768×1024, dan 1280×800 di proyek kosong; 438 dari 438 lagi dengan autoload GoRuntime; satu ekspor Web; nol kegagalan kontras pada keenam tema. Godot 4.6 serta perangkat Android atau iOS sungguhan tidak termasuk dalam jalan uji ini.","python3 addons/gohud/tools/check_contrast.py bash addons/gohud/tools/check_all.sh",-1],[0,"release-versions","Versi rilis",1,"Jalan yang berhasil memperbarui plugin.cfg, GoUi.VERSION, dan CHANGELOG.md sekaligus, memindahkan catatan Unreleased menjadi entri bertanggal. Jalan yang gagal tidak mengubah apa pun, dan ZIP yang sudah ada tidak pernah ditimpa. ZIP-nya tidak menyertakan situs web ini, berkas uji, dan tools.","bash addons/gohud/tools/package.sh # 1.0.1 → 1.0.2 · builds/1.0.2/gohud-1.0.2.zip bash addons/gohud/tools/package.sh --increase-minor-version # 1.0.1 → 1.1.0",15],[0,"this-site","Situs ini",1,"Halaman-halamannya HTML biasa di dalam www/ — bahasa Inggris di akar, bahasa Korea di ko/. Sebuah workflow GitHub Actions menerbitkan folder itu sebagai akar situs.","python3 addons/gohud/tools/make_site.py # glosarium dan tabel kenop skin, dibuat dari kode sumber python3 addons/gohud/tools/check_site.py # tautan, jangkar, bahasa, glosarium, tabel hasil generasi bash addons/gohud/tools/site_shots.sh /tmp/shots # tangkapan layar desktop dan ponsel untuk setiap halaman",15],[1,"ai-first","Jalan tercepat — biarkan agen AI yang memasang",0,"Satu blok teks, ditempel ke Claude Code, Codex, Cursor, atau Gemini CLI, memasang skill sekaligus add-on lalu menjelaskan gohud padamu. Lewat jalan itu, tak satu pun di bawah kartu ini diperlukan. Buka halaman AI SKILL →","",-1],[1,"install","Instalasi",0,"Letakkan folder add-on ke dalam proyek Anda. Tidak ada lagi yang perlu disiapkan.","",-1],[1,"from-the-asset-store-or-a-release-zip","Dari Asset Store atau ZIP rilis",1,"Ekstrak ke akar proyek sehingga terbentuk res://addons/gohud/. Itu saja. Bila mau, aktifkan Project → Project Settings → Plugins → gohud.","",19],[1,"as-a-git-submodule","Sebagai submodule git",1,"Akar repositori adalah folder add-on itu sendiri, jadi ia mendarat persis di tempat yang diharapkan Godot. Sunting langsung di tempat, commit dan push di dalam addons/gohud, lalu commit penunjuk submodule di game Anda. Godot 4.6 atau yang lebih baru wajib. gohud memakai API yang diperkenalkan di 4.5 (DPITexture, FoldableContainer, properti aksesibilitas), jadi pada versi yang lebih lama ia gagal saat parsing. 4.6 adalah batas bawah yang didukung, tercatat di GoUi.MIN_ENGINE.","git submodule add https://github.com/thruthesky/gohud.git addons/gohud git submodule update --init git -C addons/gohud checkout v1.0.0 # opsional: kunci ke satu tag atau commit",19],[1,"start","Mulai cepat",0,"Setiap widget cukup .new() dan add_child() — tanpa file scene, tanpa autoload.","",-1],[1,"pick-a-look-before-building-ui-optional","Pilih tampilan sebelum membangun UI (opsional)",1,"","GoUi.use_preset(GoThemePresets.SCIFI_DARK) # default_dark dipakai kalau baris ini dilewati",22],[1,"a-confirmation-you-await","Konfirmasi yang bisa Anda await",1,"Berikan destructive = true (argumen terakhir) dan tombol konfirmasi digambar sebagai tombol bahaya berisi penuh.","var dialogs := GoDialogs.new() add_child(dialogs) if await dialogs.confirm(\"Hapus simpanan\", \"Tindakan ini tidak bisa dibatalkan.\"): delete_save()",22],[1,"a-bottom-sheet-with-a-sticky-search-field-and-fo","Lembar bawah dengan kolom pencarian dan footer yang menempel",1,"Kenapa baris yang menempel dipisahkan dari body yang bergulir. Taruh tombol konfirmasi dan batal di body dan daftar yang panjang akan mendorongnya keluar layar. footer() selalu terlihat.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Inventaris\") sheet.toolbar().add_child(GoStyle.line_edit(\"Cari…\")) sheet.toolbar().visible = true for item in items: sheet.body.add_child(GoStyle.list_button(GoIconSet.BOX, item.name, _use.bind(item), Color.TRANSPARENT, item.description, false)) sheet.footer().add_child(GoStyle.button(\"Tutup\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",22],[1,"a-hud-corner","Satu sudut HUD",1,"","var corner := GoHudAnchor.new() corner.spot = GoHudAnchor.Spot.TOP_LEFT corner.landscape_spot = GoHudAnchor.Spot.TOP_RIGHT add_child(corner) var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) corner.add_child(hp) hp.set_values(320, 500)",22],[1,"content-that-keeps-clear-of-the-hud","Konten yang menjauh dari HUD",1,"Setiap persegi dihindari ke arah yang paling sedikit memakan luas — ke bawah pada ponsel potret, ke samping pada lanskap. Bagaimana HUD menghindari dirinya sendiri →","form.avoid_hud = true # menjauh dari setiap GoHudAnchor yang terlihat joystick_anchor.reserve_space = false # …kecuali yang hanya muncul di bawah jari notice_anchor.avoid_peers = true # toast turun ke bawah HUD tetap alih-alih menutupinya",22],[1,"examples","Contoh yang bisa Anda jalankan",0,"Tiga cara melihat gohud sebelum menulis satu baris pun — tidak satu pun butuh server atau autoload. Contoh Cara membuka Apa yang ditampilkan Galeri examples/gallery/gallery.tscn · F6 Setiap widget, pemilih untuk setiap preset yang terpasang, dan set ikon lengkap Abad pertengahan examples/medieval/medieval.tscn · F6 Lembar karakter, tas, dan jurnal misi; tombol-tombolnya menukar besi dan perkamen serta membuka rincian benda Aplikasi demo cd examples/demo && godot Layar beranda yang membuka galeri, tur berpemandu 15 bab, layar etalase, dan tampilan abad pertengahan, lengkap dengan widget yang hidup dan satu kartu untuk tiap kelas Aplikasi demo tidak butuh penyiapan: bila tautan add-on atau cache impornya tidak ada ia akan memberi tahu, memperbaiki foldernya, lalu membuka dirinya kembali. Layar berandanya membuka tiap contoh di dalam jendela yang sama — tekan 1–4 atau klik salah satu barisnya, dan bilah di sepanjang bagian atas membawa Anda kembali. Di dalam turnya, C mengalihkan mode Sinema, F11 layar penuh, Spasi menjeda (atau memainkan widget yang sedang dilihat saat menjelajah), tombol panah mengganti bab, dan Escape kembali ke layar Mulai. Memakai agen coding AI? Buka ketiganya dengan satu perintah →","cd examples/demo && godot # layar beranda; menautkan dan mengimpor saat pertama dijalankan bash examples/demo/run.sh # aplikasi yang sama, dari akar add-on bash examples/demo/run.sh -- --open=gallery # lewati layar berandanya bash examples/demo/run.sh -- --explore=surfaces # langsung membuka satu bab tur bash examples/demo/run.sh --record /tmp/gohud-demo.avi # rekaman tur 1080p / 60 fps",-1],[2,"copy","Tempelkan ini ke agen codingmu",0,"Buka proyek Godot di agen, tempel blok di bawah, lalu kirim. Ia memasang skill dan add-on, lalu menceritakan apa saja yang bisa dilakukan gohud. Blok ini sengaja ditulis dalam bahasa Inggris — itu yang paling andal dibaca setiap agen. Pertanyaanmu sendiri boleh bahasa apa pun; skill menjawab dalam bahasa yang kamu pakai.","Install gohud for this Godot 4.6+ project, then use it for all game UI (menus, HUD bars, quick slots, dialogs, bottom sheets, forms, themes). 1. Install the gohud AI skill. Claude Code: claude plugin marketplace add thruthesky/gohud claude plugin install gohud@gohud Any other agent (Codex, Cursor, Gemini CLI, ...): git clone --depth 1 https://github.com/thruthesky/gohud.git /tmp/gohud Copy /tmp/gohud/skills/gohud into whichever of these folders this agent reads: ~/.claude/skills/gohud, .claude/skills/gohud, .agents/skills/gohud. 2. Install the add-on itself, if addons/gohud/plugin.cfg is missing here. In a git repository: git submodule add https://github.com/thruthesky/gohud.git addons/gohud Otherwise copy the clone to addons/gohud without its .git folder. Then run: godot --headless --path . --import 3. Restart yourself so the skill loads, then tell me what gohud can do and how to preview it. Docs: https://thruthesky.github.io/gohud/",-1],[2,"agents","Di mana tiap agen menyimpan skill",0,"Mau pasang manual? Letakkan folder skills/gohud di tempat yang dibaca agenmu. Yang ada lebih dulu yang dipakai. Agen Folder ditaruh di mana Bentuk perintah Claude Code — plugin claude plugin install gohud@gohud /gohud:preview · /gohud:features Claude Code — skill saja ~/.claude/skills/gohud /gohud preview · /gohud features Claude Code — proyek ini saja .claude/skills/gohud /gohud preview Codex · Cursor · Gemini CLI — lainnya .agents/skills/gohud —","",-1],[2,"commands","Perintah yang kamu dapat",0,"","",-1],[2,"gohud-preview-the-widget-gallery","/gohud:preview — galeri widget",1,"Membuka galeri: setiap widget, pemilih untuk keenam preset, dan set ikon lengkap. Ketik di dalam proyek Godot Anda dan ia memakai yang milik Anda sendiri di addons/gohud; bila tidak ada, ia memakai salinan bawaan plugin, atau klon yang baru. Ia berjalan di proyek kotak pasir sekali pakai, sehingga autoload dan cache impor Anda tidak terganggu, dan jendelanya tetap terbuka sampai Anda menutupnya.","",31],[2,"gohud-preview-demo-the-19-chapter-guided-tour","/gohud:preview demo — tur berpemandu 15 bab",1,"Membuka demo pada layar awalnya. Mulai demo memainkan tur dengan input sungguhan; Jelajahi widget membiarkan Anda mencoba satu widget secara manual. Tombol-tombol yang tercantum di Contoh berlaku juga di sini.","",31],[2,"many-other-commands","Banyak perintah lainnya",1,"Perintah Fungsinya /gohud:preview medieval Lembar karakter, tas, dan jurnal misi dalam preset abad pertengahan /gohud:preview demo --explore hud Demo yang langsung dibuka pada satu bab — hud buttons inputs selection lists data states surfaces prompt touch coach scrolling forms anchors theming /gohud:preview gallery --preset scifi_dark Galeri dalam satu preset; tambahkan --phone untuk jendela ponsel 390×844 atau --size 1920x1080 untuk ukuran apa pun /gohud:preview res://ui/main_menu.tscn Scene milik proyek Anda sendiri, dijalankan di dalam proyek itu /gohud:preview list Semua sasaran, id preset, dan kunci bab demo /gohud:preview gallery --check Uji asap headless tanpa jendela — gagal bila ada kesalahan skrip /gohud:features Setiap fitur, dikelompokkan, masing-masing satu baris kode /gohud:features hud Satu bidang secara mendalam — surfaces hud style theming icons i18n accessibility config Perintah pratinjau butuh Godot 4.6 atau lebih baru di PATH.","",31],[2,"ask","Atau tinggal minta saja",0,"Atau tinggal minta saja. Skill-nya mengajarkan seluruh API gohud kepada agen, jadi permintaan biasa pun jalan — \"Buatkan menu jeda dengan gohud\". Bila dipasang sebagai skill biasa di ~/.claude/skills/gohud, perintahnya memakai spasi: /gohud preview demo, /gohud features. Pratinjau membutuhkan Godot 4.6 atau yang lebih baru di PATH Anda, atau berikan --godot /path/to/godot.","",-1],[4,"gosurface-the-shell","GoSurface — cangkangnya",1,"Popup, lembar, dan dropdown semuanya memakai yang satu ini. Ia mengurus area aman, keyboard virtual, header dan footer yang menempel, body yang bergulir, jendela mana yang paling atas, pemulihan fokus, kepemilikan tombol kembali, dan tarik untuk mengubah ukuran. Penempatan Tampak seperti Dipakai untuk CENTER Sebuah kartu di tengah Konfirmasi, setelan BOTTOM Sebuah lembar yang naik dari bawah Daftar, halaman pengelolaan ANCHOR Sebuah kartu yang disematkan di samping sebuah kontrol Dropdown, menu konteks Ia tidak menghapus dirinya sendiri. Menanggapi close_requested — menyembunyikan atau membebaskannya — adalah tugas layar yang memilikinya, karena cangkangnya tidak bisa tahu kenapa ia ditutup (simpan lalu tutup, atau buang).","",-1],[4,"gosheet-a-page-from-the-bottom","GoSheet — sebuah halaman dari bawah",1,"Ia memiliki CanvasLayer sendiri, jadi ia pasti berada di atas HUD. open() mengosongkan body dan mematikan tombol kembali serta baris yang menempel — tombol mati di layar yang tidak punya tempat untuk kembali akan terbaca sebagai rusak.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Inventaris\") sheet.toolbar().add_child(GoStyle.line_edit(\"Cari…\")) sheet.toolbar().visible = true sheet.footer().add_child(GoStyle.button(\"Tutup\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",-1],[4,"godialogs-confirmations-you-await","GoDialogs — konfirmasi yang bisa Anda await",1,"confirm(title, body, ok_text, cancel_text, extra, args, destructive) — semua yang ada setelah body bersifat opsional, dan alert() bekerja dengan cara yang sama dengan satu tombol saja. Setel destructive untuk sesuatu yang tak bisa dibatalkan: tombol konfirmasinya berubah menjadi tombol GoStyle.Tone.DANGER_SOLID yang berisi penuh. Pada tema terang, label bahaya yang dironai harus digelapkan sampai terbaca seperti teks hitam; tombol berisi penuh mempertahankan teks putih di atas merah. Nada warnanya diterapkan ulang pada setiap pemanggilan karena satu jendela dipakai berulang, dan confirm() kedua ketika satu dialog masih terbuka langsung mengembalikan false. confirm_key() menerima kunci terjemahan. Tata letak tombol. action_layout secara default adalah VERTICAL (aman untuk terjemahan yang panjang), HORIZONTAL untuk satu baris dengan lebar separuh-separuh, atau AUTO, yang memakai satu baris hanya bila kedua labelnya muat pada separuh kartu dalam satu baris dan menumpuknya bila tidak. action_gap adalah jarak antar tombol dan body_gap jarak di atasnya — buat yang terakhir lebih lebar daripada jarak antartombol agar pertanyaan dan pilihannya terbaca sebagai dua bagian. Untuk satu dialog saja, panggil set_next_action_layout() sebelum membukanya. Baris tombolnya dibangun saat sebuah dialog pertama kali dibuka, jadi GoDialogs yang di-autoload tidak menambah apa pun saat startup.","if await dialogs.confirm(\"Hapus simpanan\", \"Tindakan ini tidak bisa dibatalkan.\"): delete_save()",-1],[4,"goform-a-width-capped-form","GoForm — formulir berlebar terbatas",1,"Ia menjamin label keturunannya membungkus baris. Tanpa itu, satu kalimat panjang akan merentang menjadi satu baris yang lebar minimumnya melebihi layar, dan sisi-sisinya terpotong — Anda bahkan tak bisa tahu sedang berada di layar apa. Menyalakan pembungkusan baris secara manual per scene selalu terlupakan.","",-1],[4,"goscroll-touch-scrolling","GoScroll — gulir sentuh",1,"Taruh satu hal saja di dalamnya. Header dan baris tombol tempatnya di luar — daftar yang panjang tidak boleh mendorongnya keluar layar. use_panel_edge() memindahkan bilah gulirnya ke dalam padding kartu yang sudah ada sementara kontennya mempertahankan indentasinya.","",-1],[5,"gonotice-snackbar","GoNotice — snackbar",1,"Ia tidak pernah mencegat input. Sebuah pemberitahuan itu dibaca, bukan ditekan. Ia tidak mengambil fokus, tidak menghalangi input game, dan tombol di bawahnya masih bisa ditekan. Bila butuh konfirmasi pakailah GoDialogs; bila butuh pilihan, GoPromptCard.","",-1],[5,"gopromptcard-a-question-that-does-not-block","GoPromptCard — pertanyaan yang tidak menghentikan jalannya game",1,"Mengambang di salah satu sisi tanpa selubung. Game-nya terus berjalan.","",-1],[5,"gocoachmark-guided-tour","GoCoachMark — tur berpemandu",1,"Menunjuk kontrol sungguhan satu per satu. Hanya kartunya yang menerima input, sehingga menekan kontrol yang disorot itu sendiri akan melanjutkan tur — \"tekan di sini\" menjadi sebuah tindakan, bukan sekadar kalimat. title dan body boleh berupa kunci terjemahan atau teks biasa. Langkah yang sasarannya sudah menghilang akan dilewati.","tour.start([ {\"target\": bag_button, \"title\": \"Tas\", \"body\": \"Semua yang Anda pungut mendarat di sini.\"}, {\"target\": map_button, \"title\": \"Peta\", \"body\": \"Tekan untuk membuka peta lengkap.\"}, ])",-1],[6,"the-small-things-decide-whether-it-looks-good","Hal-hal kecil yang menentukan bagus atau tidaknya",1,"Poles panel besarnya sesuka Anda — yang selalu menyita perhatian justru sesuatu yang kecil: satu kata terbelah dua, pendar yang terpotong, slot yang sempit. Empat hal semacam itu ditunjukkan pada 2026-09-13 lalu diperbaiki di widget dan temanya, bukan di layar demonya, sehingga setiap layar mendapat hasil yang sama. Apa yang terlihat Penyebab Perbaikan Done pada coach mark menjadi Don/e Tombol dengan pembungkusan baris menyala mengurangi lebar teksnya dari lebar minimumnya — sempitkan sedikit dan ia patah di tengah kata GoStyle.fit_words(): satu kata tidak pernah dipenggal; beberapa kata boleh membungkus, tetapi kata terpanjang selalu muat — dinilai pada teks yang ditampilkan, bukan pada kunci terjemahannya, dan diterapkan ulang oleh formulir ketika bahasanya berganti Pendar tombol selebar layar terpotong secara vertikal di sisi kiri Kontainer gulir memotong di tepinya, tanpa kecuali. Hanya sisi kanan yang selamat, berkat celah relnya GoScroll meminjam padding induknya untuk mendorong tepinya 12dp keluar lalu mengembalikannya di dalam — kontennya tidak bergeser Waktu, ikon, dan jumlah menumpuk vertikal di dalam sebuah slot Tiga baris di dalam 48dp Ikon besar di tengah, pintasan di kiri atas, jumlah sebagai lencana di kanan bawah, sisa waktu sebagai lencana di atas ikonnya — panel lencananya berasal dari badge_box() milik skin Dropdown datar tanpa pilihan yang terlihat Sorotan butir memakai panel tombol; penanda radionya adalah default mesin yang samar Panel sorotan tersendiri (rona aksen lembut), gambar radio yang sama dengan kotak centang, tinggi butir yang pas untuk sentuhan Dropdown — panel sorotan dan penanda radio Slot — lencana sudut dan sisa waktu (sci-fi) Berikan deskripsi pada tombol yang hanya berisi ikon lewat GoStyle.icon_button(icon, action, -1, tooltip_key) — tooltip untuk pengguna tetikus dan nama aksesibilitas untuk pembaca layar keduanya berasal dari satu nilai itu. gohud menggambar tooltip-nya sendiri: default mesinnya memecah teks satu karakter per baris ketika perhitungan lebarnya meleset (terukur selebar 1dp). Kartu coach mark menjauh dari perabot layar Pada mode lanskap, kartunya dulu dilempar ke tepi paling atas atau paling bawah — persis tempat header dan bagian HUD berada; di dalam demo ia mendarat di atas → × milik header. Kini ia tetap sejajar dengan sasarannya, memutari setiap GoHudAnchor yang memesan ruang, dan menerima hal-hal lain yang harus dihindari lewat keep_clear. Ia bergerak sependek mungkin untuk melewati penghalang tanpa menutupi sasarannya, dan tetap diam bila layarnya terlalu kecil untuk melewati semuanya — bertumpuk lebih baik daripada menghilang. Kedalamannya — agar ia terbaca di atas halaman — berasal dari kenop skin (float_shadow_size, float_shadow_lift, float_shadow_alpha; skin bersudut potong memakai float_glow_size).","tour.keep_clear = [header_bar, toolbar] # perabot layar yang bukan anchor",-1],[6,"screens-with-a-mouse-and-a-keyboard","Layar dengan tetikus dan papan ketik",1,"Jari tidak punya keadaan hover. Bangun hanya untuk seluler dan dua keadaan khas desktop luput dari pemeriksaan — dan salah satunya memang rusak: cincin fokus gohud tidak terlihat pada tombol primer. Panelnya berwarna aksen dan cincinnya pun begitu: 1,00:1, warna yang sama digambar di atas dirinya sendiri. Bergerak dengan papan ketik, tak ada cara untuk tahu Anda sedang berada di mana. Dari atas ke bawah: normal · hover · fokus. Tombol berisi penuh mendapat cincin yang kontras dengan panelnya. Tombol berisi penuh (GoPrimaryButton, GoDangerSolidButton) memakai cincin yang kontras dengan panelnya sendiri — gelap pada tema gelap, putih pada tema terang, kurung penanda sasaran yang gelap pada sci-fi. Pemeriksa kontras mengukur cincin fokus terhadap panel tempatnya berada, sehingga aturannya bertahan saat paletnya berubah (WCAG 2.4.11 meminta 3:1 pada penanda fokus).","",-1],[6,"hud-widgets","Widget HUD",0,"","",-1],[6,"gohudanchor-nine-spots","GoHudAnchor — sembilan titik",1,"Menghormati area aman dan margin tepi. Berikan landscape_spot dan ia berpindah saat lanskap — kontrol yang duduk di tengah bawah pada mode potret bisa pindah ke kanan bawah. Kenapa ia ada. Ditulis manual untuk tiap bagian HUD, anchor dan offset-nya akan melenceng: bar darah berakhir di bawah lubang kamera pada perangkat ber-notch, dan tombol kontrol mendarat di atas gesture bar saat lanskap. Hitung-hitungan itu tinggal di satu tempat. Menjaga konten tidak masuk ke bawah HUD Ketika layar yang bergulir berbagi tampilan dengan HUD, kontennya menyelinap ke bawahnya dan kedua kumpulan teksnya bertumpuk sampai tak satu pun terbaca. Itu terjadi dua kali di add-on ini: teks contoh sebuah kolom masukan terjepit di antara slot cepat, dan kenop sakelar pada setelan mendarat di atas bar darah. Setiap persegi dihindari ke arah yang paling sedikit memakan luas. Bar di kanan atas diputari ke bawah pada ponsel potret (13% dari tingginya) dan ke samping pada lanskap (21% dari lebarnya) — menghindarinya secara vertikal pada lanskap akan memakan 27% dari layar. Ruang yang sudah direlakan dikurangkan lebih dulu sebelum persegi berikutnya diukur. Bagian-bagian HUD juga bertabrakan satu sama lain Kesembilan titik itu membagi layar; mereka tidak menjamin bagian-bagiannya saling luput. Sebuah snackbar lebar di tengah atas mendarat tepat di atas bar darah di kanan atas, menyembunyikan nilainya — Anda tidak bisa membaca berapa sisa darahnya. Ia menyingkir secara vertikal saja — menyingkir ke samping juga akan membuat toast yang terpusat muncul di tempat yang berbeda-beda setiap kali. Dan ia hanya menghindari bagian yang tidak ikut menyingkir sendiri: kalau keduanya mengalah, keduanya akan bertukar tempat selamanya.","form.avoid_hud = true # menjauh dari setiap GoHudAnchor yang terlihat joystick_anchor.reserve_space = false # …kecuali yang hanya muncul di bawah jari notice_anchor.avoid_peers = true # turun ke bawah HUD tetap notice_anchor.reserve_space = false # dan tidak mendorong halamannya selagi ia muncul",46],[6,"gobar-health-mana-experience","GoBar — darah, mana, pengalaman",1,"Perubahannya dilandaikan selama 0,18 detik — bar darah yang melompat tidak memberi tahu Anda seberapa keras Anda terpukul. reduce_motion membuatnya seketika. Angka besar disingkat menjadi 12.3k supaya lebar bar-nya tidak bergetar saat jumlah digitnya berubah.","var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) # token khusus isian hp.set_values(320, 500) # \"320 / 500\"",46],[6,"goslot-one-quick-slot","GoSlot — satu slot cepat",1,"Ikon, jumlah, waktu jeda, dan pintasan pada satu muka. Menggantung lencana pada lingkaran kecil membuat tiap slot punya lebar berbeda dan barisannya goyah. Ukuran terlihat dan ukuran sentuh berbeda. Slot yang berdempetan punya kotak sentuh 48dp yang saling tumpang tindih; tumpang tindihnya jatuh ke slot yang pusatnya lebih dekat — beri tahu mereka satu sama lain lewat touch_peers. keyboard_focus mati secara default, supaya barisan delapan slot tidak menghalangi pengguna papan ketik dari setiap kontrol setelan dalam urutan Tab. Nyalakan bila papan ketik atau gamepad adalah satu-satunya input.","",46],[6,"gojoystick-virtual-stick","GoJoystick — stik virtual",1,"Mode Perilaku FIXED Selalu di tempat yang sama — mudah ditemukan tanpa melihat FOLLOW Muncul di tempat ibu jari mendarat RELATIVE Terus mengikuti ibu jari setelah muncul — nyaman untuk gerakan panjang Vector2 dari moved panjangnya 0–1, jadi Anda bisa langsung mengalikannya dengan sebuah kecepatan; nilainya tidak berubah mengikuti ukuran layar atau DPI.","",46],[6,"goiconbutton-looks-small-presses-large","GoIconButton — terlihat kecil, ditekan besar",1,"Hanya aman selama saudara-saudaranya mengabaikan input. Bila area yang diperlebar itu menutupi tombol berikutnya, tombol itu berhenti merespons. Tombol ikon yang berjajar butuh touch_peers.","",46],[7,"gosnackbar-the-message-that-places-itself","GoSnackbar — pesan yang menempatkan dirinya sendiri",1,"Duduk di bawah (atau di atas), di atas area aman dan keyboard, lalu pergi dengan sendirinya. Tanpa itu Anda menulis lapisannya, penempatannya, pewaktunya, dan pembongkarannya di setiap layar yang harus mengatakan \"tersimpan\". Pesan-pesannya mengantre alih-alih saling menimpa, dan pengulangan baris yang sama digabung — server yang gagal empat kali sedetik tidak lagi menumpuk empat menit peringatan. Snackbar tanpa tombol meneruskan input, jadi game di bawahnya terus berjalan. Ia bukan tempat untuk menanyakan sesuatu. Ia pergi dengan sendirinya, jadi pemainnya bisa saja tidak pernah melihatnya. Konfirmasi yang tak bisa dibatalkan tempatnya di GoDialogs. Tombol di sini harus bersifat opsional — Batalkan, Rincian, Coba lagi. GoNotice adalah separuh lainnya dari pasangan ini: ia tidak pernah mengambil input atau fokus, dan layar yang memilikinya yang menentukan ke mana ia pergi. Ia tidak bisa memuat tombol; yang ini bisa.","snack.show_text(\"Tersimpan\", GoTheme.SUCCESS) # Kesempatan untuk membatalkan — 0 adalah tombol pertama, -1 berarti waktunya habis if await snack.post({\"text\": \"Item dibuang\", \"actions\": [\"Batalkan\"]}) == 0: restore_item()",-1],[7,"gospinner-a-wait-with-no-end-in-sight","GoSpinner — menunggu tanpa tahu kapan berakhirnya",1,"Game yang berbicara dengan server membutuhkan ini lebih daripada apa pun di halaman ini: layar yang diam terbaca sebagai crash. Satu panggilan mengubah tombol yang Anda tekan menjadi spinner di tempatnya. Tombolnya mempertahankan ukurannya — labelnya menjadi transparan alih-alih hilang, jadi barisnya tidak melompat — dan ia dimatikan selagi berputar. Bagian kedua itulah intinya: sebuah pembelian tidak boleh terpicu dua kali selagi Anda await. Dengan reduce_motion menyala ia tidak berputar; tiga titik berdenyut sebagai gantinya. Kemajuan yang bisa Anda ukur itu GoBar. Spinner tidak menjanjikan apa pun tentang kapan ia berakhir.","GoSpinner.busy(buy_button, true) var ok := await server.purchase(item) GoSpinner.busy(buy_button, false)",-1],[7,"gobadge-the-unread-dot-the-new-tag-the-99","GoBadge — titik belum dibaca, tanda BARU, dan 99+",1,"Ia menggantung di pojok kanan atas induknya dengan anchor, jadi ia mengikuti induk yang ukurannya baru ditentukan belakangan, dan memasangnya dua kali mengembalikan lencana yang sama. Pakai angka bila jumlahnya mengubah apa yang dilakukan pemain, dan titik bila yang penting hanya \"ada sesuatu\". Warna teksnya dipilih agar kontras dengan warna apa pun yang dipakai skin untuk mengecat lencananya — tidak pernah diasumsikan putih — dan ia membawa nama aksesibilitas, karena titik berwarna tidak mengatakan apa-apa kepada pembaca layar.","GoBadge.attach(mail_button, unread_count) # menyembunyikan diri saat nol GoBadge.attach(shop_button, 0, \"BARU\") GoBadge.attach(friend_button, 3, \"\", true) # sebuah titik — \"ada sesuatu di sana\"",-1],[8,"gofield-the-row-that-can-be-wrong","GoField — baris yang bisa salah",1,"Satu baris di atas formulir berisi lima kolom yang berbunyi \"periksa masukan Anda\" tidak memberi tahu kolom yang mana. Hal satu itulah yang membuat orang meninggalkan pendaftaran. Petunjuknya bersembunyi selagi pesan kesalahannya tampil, jadi barisnya tidak bertambah satu baris dan mendorong segala sesuatu di bawahnya, dan teks kesalahannya digabungkan ke dalam nama aksesibilitas kontrolnya — garis tepi merah saja tidak mengatakan apa-apa kepada orang yang tidak bisa melihat merah. GoStyle.field() adalah versi statisnya: label, kontrol, petunjuk, tanpa keadaan kesalahan. Pakai pabriknya bila tak ada yang bisa salah, dan node-nya untuk apa pun yang bisa ditolak server.","var name_field := GoField.make(\"Nama karakter\", GoStyle.line_edit(\"2-12\"), \"Tidak bisa diubah nanti\") name_field.set_error(\"Nama itu sudah dipakai\") # servernya menolak name_field.clear_error()",-1],[8,"goinputgroup-an-input-welded-to-its-button","GoInputGroup — masukan yang dilas ke tombolnya",1,"Yang ia pecahkan adalah sudut. Dua bentuk membulat yang bertemu di tengah tampak terjepit, dan jarak bawaannya membuat keduanya terbaca sebagai dua objek. Sudut luarnya tetap bulat, yang bersentuhan menjadi siku — pada setiap keadaan tombol, kalau tidak kelompoknya terbelah begitu ditekan. Skin ber-chamfer sama sekali tidak punya properti sudut, jadi di sana ia membiarkannya apa adanya dan muka-muka sikunya bertemu dengan rapi.","GoInputGroup.make(GoStyle.line_edit(\"Pesan\"), {\"suffix\": GoStyle.icon_button(&\"send\", send)}) GoInputGroup.make(GoStyle.line_edit(\"Nama\"), {\"prefix_icon\": &\"search\"})",-1],[8,"gocombobox-a-picker-that-searches","GoCombobox — pemilih yang bisa mencari",1,"Di bawah sepuluh entri GoStyle.select() lebih baik: satu ketukan lebih sedikit dan seluruh daftarnya terlihat. Lewat tiga puluh, memindainya jadi pekerjaan. Pencariannya mencocokkan di dalam nama, bukan hanya awalannya. Pencocokan awalan nyaris tidak menemukan apa pun pada daftar berbahasa Korea atau Jepang, yang kata pembeda dua entrinya jarang menjadi kata pertama.","var picker := GoCombobox.make(server_names, 0, \"Pilih server\") picker.picked.connect(func(i: int) -> void: connect_to(servers[i]))",-1],[8,"gocodeinput-coupon-and-gift-codes","GoCodeInput — kode kupon dan hadiah",1,"Sebuah kode jauh lebih sering ditempel dari sebuah pesan daripada diketik. Dua belas kolom sungguhan akan mematahkan penempelan di sel pertama dan kehilangan karakter ke IME, jadi satu kolom tersembunyi yang menerima teksnya dan sel-selnya digambar. ABCD-EFGH-IJKL kehilangan tanda hubungnya di jalan masuk.","var coupon := GoCodeInput.make(12, 4) coupon.completed.connect(func(code: String) -> void: server.redeem(code)) coupon.set_error(\"Sudah dipakai\")",-1],[8,"gotable-sortable-headers-selectable-rows","GoTable — kepala kolom yang bisa diurutkan, baris yang bisa dipilih",1,"numeric: true, kalau tidak peringkatnya terbalik. Dibandingkan sebagai teks, \"9124\" mengalahkan \"91240\" — dan skor, emas, serta kerusakan semuanya punya jumlah digit yang campur aduk. row_selected memberi indeks pada array asli Anda, bukan posisi setelah diurutkan. Arah pengurutannya ditunjukkan dengan sebuah glif, bukan hanya warna, dan seluruh barisnya bisa ditekan supaya tak seorang pun harus mengenai satu sel. GoStyle.table() tetap menjadi grid yang hanya bisa dibaca.","var board := GoTable.make( [{\"text\": \"Peringkat\", \"width\": 56}, {\"text\": \"Nama\"}, {\"text\": \"Skor\", \"numeric\": true}], rows) board.row_selected.connect(func(i: int) -> void: open_profile(rows[i]))",-1],[8,"gopagination-pages-or-a-more-row","GoPagination — halaman, atau baris Selengkapnya",1,"Angka itu UI untuk tetikus; pada ponsel baris Selengkapnya lebih terbaca. Halaman yang sedang dibuka tetap terpusat di jendelanya, jadi menekan berikutnya tidak mengacak ulang setiap angka. Total 0 berarti \"tidak diketahui\" dan hanya panahnya yang digambar — ia tidak mengarang jumlah halaman yang tidak diberikan kepadanya.","var pager := GoPagination.make(1, 12, func(page: int) -> void: load_mail(page)) var more := GoPagination.more(load_next) # varian yang ramah ponsel",-1],[9,"gorewardcalendar-daily-attendance","GoRewardCalendar — absensi harian",1,"Pemilih tanggal nyaris tak pernah berguna di dalam game. Bentuk kalender berguna — untuk hadiah absensi, yang pentingnya adalah Anda sedang di hari ke berapa, bukan tanggal berapa hari itu. Hanya sel hari ini yang bisa ditekan — tombol yang tidak melakukan apa-apa saat ditekan terbaca sebagai rusak. Yang sudah diambil, hari ini, dan hari mendatang berbeda dalam tiga hal sekaligus: glif centang, garis tepi aksen, dan peredupan.","var attendance := GoRewardCalendar.make(days, claimed_until) attendance.claimed.connect(func(day: int) -> void: server.claim_day(day))",-1],[9,"goradar-and-godonut-stats-at-a-glance","GoRadar dan GoDonut — statistik dalam sekali lihat",1,"Nilai radar itu 0–1 karena apa yang dihitung sebagai penuh adalah keputusan game — 120 STR mentah di samping 45 INT akan menggambar sebuah kebohongan. Nilai donatnya mentah dan ia yang membaginya untuk Anda; lewat lima potong ia meringkas sisanya, karena potongan keenam adalah seutas benang yang tak seorang pun bisa membacanya. Garis pembandingnya putus-putus, bukan sekadar warna yang lain, dan legendanya mencetak persentasenya dalam bentuk kata.","var stats := GoRadar.make({\"STR\": 0.85, \"AGI\": 0.5, \"INT\": 0.3, \"VIT\": 0.7, \"LUK\": 0.45}) stats.set_compare(with_new_sword) # hamparan bergaris putus-putus var share := GoDonut.make([{\"label\": \"Fisik\", \"value\": 620}, {\"label\": \"Sihir\", \"value\": 340}]) card.add_child(share.legend())",-1],[9,"gocarousel-banners-and-character-select","GoCarousel — banner dan pemilihan karakter",1,"Ia tidak berpindah sendiri kecuali Anda memintanya, dan lima detik adalah batas bawahnya: banner yang berganti setiap tiga detik mengambil teksnya sebelum sempat dibaca. Menyentuhnya mengatur ulang pewaktunya, dan dengan reduce_motion menyala ia tidak pernah berpindah sendiri. Titik-titiknya bisa ditekan pada ukuran sentuh minimum meskipun titik yang digambar itu kecil.","banners.set_pages([promo, event, pack]) banners.autoplay_seconds = 5.0 # mati secara default",-1],[9,"gokbd-key-hints-that-do-not-lie","GoKbd — petunjuk tombol yang tidak berbohong",1,"Tulisan \"Tekan F\" yang ditanam di kode akan terus mengatakan F setelah pemainnya mengubah pengikatan tombol — kebohongan paling umum pada UI PC. for_action() membaca InputMap; bila aksinya justru terikat ke gamepad, ia mengembalikan nilai kosong dan widget-nya bersembunyi, karena \"Tidak ada\" akan menjadi kebohongannya sendiri. Pada Android dan iOS ia menyembunyikan dirinya.","hint.add_child(GoKbd.for_action(&\"interact\")) # membaca pengikatan yang sebenarnya",-1],[10,"godrawer-the-side-panel","GoDrawer — panel samping",1,"GoSheet datang dari bawah, dan itu tepat untuk ponsel yang dipegang tegak. Pada tablet atau desktop lembar yang sama menutupi game-nya; laci datang dari samping sebagai gantinya. Panelnya mencapai tepi layar tetapi kontennya tetap di dalam area aman, kalau tidak sudut membulatnya akan memotong baris pertama. LEFT berarti kiri layar bahkan dalam bahasa Arab; nyalakan follow_text_direction bila \"sisi awal\" yang menjadi intinya, dan ia akan berbalik pada RTL.","bag.side = GoDrawer.Side.RIGHT bag.open(\"Tas\")",-1],[10,"gopopover-the-anchored-card","GoPopover — kartu yang disematkan",1,"Ini adalah penempatan tersemat milik GoSurface dengan lapisan, permukaan, anchor, dan pembongkarannya sudah terpasang — sepuluh baris yang ditulis setiap game berulang-ulang. Hanya satu yang terbuka pada satu waktu, karena kartu yang bertumpuk mengubur layarnya dan tak seorang pun bisa tahu kartu mana milik slot mana. Selubungnya transparan: kartu yang Anda buka untuk membandingkan perlengkapan tidak boleh menggelapkan perlengkapannya. Ia bukan tooltip hover. Sentuhan tidak punya hover, jadi apa pun yang hanya bisa dimunculkan tetikus itu tak terlihat oleh separuh pemain Anda.","GoPopover.open(slot, item_card(item))",-1],[10,"gocontextmenu-long-press-and-right-click","GoContextMenu — tekan lama dan klik kanan",1,"PopupMenu sudah ada di dalam engine. Yang tidak ada adalah gesturnya: setengah detik untuk membuka, dibatalkan begitu jarinya bergerak, jadi menggulir sebuah daftar tidak pernah memunculkan menu. Berikan sebuah Callable alih-alih array bila entrinya bergantung pada apa yang Anda tekan. Tekan lama butuh jalan masuk kedua. Tak seorang pun menemukan gestur tersembunyi — pasangkan dengan tombol ⋯ yang terlihat (open_at()), sebuah ikon, atau coach mark saat pertama kali dijalankan.","GoContextMenu.attach(item_slot, [ {\"text\": \"Pakai\", \"action\": use}, {\"separator\": true}, {\"text\": \"Buang\", \"action\": drop, \"danger\": true}, ])",-1],[10,"goconsole-the-developer-console","GoConsole — konsol pengembang",1,"Perintah cheat dan debug, dengan palet yang menyaring selagi Anda mengetik supaya tak seorang pun harus menghafalnya, dan riwayat pada tombol panah. Ia duduk di atas segalanya, jadi Anda bisa men-debug di atas sebuah dialog. Ia menolak terbuka pada build rilis. debug_only menyala secara default; perintah cheat di tangan pemain mengakhiri ekonomi sebuah game pada hari pertama.","console.register(\"give\", \"Berikan sebuah item: give <id> <count>\", give) console.toggle()",-1],[11,"list-rows-with-a-description","Baris daftar dengan deskripsi",1,"Baris dengan baris kedua mendapat padding atas dan bawah yang sama, lebih lapang daripada baris satu baris, dan pasangan judul/deskripsinya tetap terpusat secara vertikal di samping ikonnya — juga ketika sebuah kontainer merentangkan barisnya menjadi lebih tinggi, dan setelah deskripsinya membungkus menjadi beberapa baris. Seluruh barisnya tetap satu target ketukan. Baris dua baris, slot, dan bar pada contoh abad pertengahan — pemanggilan pabrik yang sama di bawah medieval_light.","GoStyle.list_button(GoIconSet.SWORD, \"Penjaga Sumpah\", _inspect, Color.TRANSPARENT, \"Pedang panjang / Serangan 42\", false)",-1],[11,"flowing-rows","Baris yang mengalir",1,"Taruh kontrol ke dalam wrap_row pada lebar alaminya. Dengan pembungkusan baris dibiarkan menyala, lebar minimum sebuah tombol turun hampir menjadi nol dan barisnya mengukur selnya berdasarkan itu — labelnya menciut menjadi satu karakter per baris. Pabriknya mencegah hal itu untuk Anda.","",-1],[11,"never-leave-an-empty-list-empty","Jangan pernah membiarkan daftar kosong benar-benar kosong",1,"Orang membaca layar kosong sebagai rusak.","page.add_child(GoStyle.empty_state(GoIconSet.BOX, \"Belum ada apa-apa di sini\"))",-1],[11,"hooks","Kait untuk subkelas",0,"Setiap tempat sebuah widget anak dibangun melewati sebuah metode yang bisa ditimpa, sehingga proyek yang menurunkan tipe-tipe gohud bisa menempatkan subkelasnya sendiri di dalam widget tanpa menyalin kode. Kait Widget Default _make_scroll() GoCoachMark, GoSurface GoScroll.new() _make_close_button() GoPromptCard, GoSurface GoIconButton.new() _make_surface() GoSheet, GoDialogs GoSurface.new() _should_pause() GoCoachMark Menyembunyikan kartunya selagi sebuah modal terbuka","",-1],[13,"pick","Memilih salah satu",0,"Satu baris itu menukar tema, skin, dan ikon. Dari editor, gunakan Project Settings → Gohud → Theme → Preset; dari resource setelan, GoConfig.preset.","GoUi.use_preset(GoThemePresets.SCIFI_DARK)",-1],[13,"keeping-one-field-your-own","Mempertahankan satu kolom sebagai milik Anda",1,"Menyetel theme, skin, atau icons secara eksplisit mengalahkan preset.","GoUi.use_preset(GoThemePresets.SCIFI_DARK) GoUi.config.icons = my_icons # ikon Anda, sisanya dari preset",73],[13,"the-six-built-in-presets","Enam preset bawaan",1,"Preset Panel Skin · ikon default_dark · default_light Panel StyleBoxFlat membulat dengan skala bayangan bertingkat; tombol primer terangkat lalu tenggelam saat ditekan GoSkin · 84 ikon default scifi_dark · scifi_light Panel GoStyleBoxCut bersudut potong dengan tepi neon dan pendar; penanda fokus GoStyleBoxBracket GoSkinSciFi — joystick heksagonal · ikon default medieval_dark · medieval_light Bingkai tempaan GoStyleBoxMedieval — besi dan kulit, atau perkamen — dengan paku keling dan ornamen sudut pada menu GoSkinMedieval · 16 ikon ukiran di atas ikon default","",73],[13,"medieval","Abad pertengahan: besi, kulit, dan perkamen",0,"medieval_dark memadukan besi gelap dan kulit dengan emas antik. medieval_light memakai perkamen dan tinta. Keduanya memakai GoSkinMedieval, widget yang sudah ada, dan 16 ikon orisinal dengan detail ukiran; ikon navigasi kembali ke set aslinya. Pilih presetnya sebelum membuat UI Anda. Penimpaan eksplisit lewat GoConfig.theme, skin, atau icons tetap diutamakan. Buka res://addons/gohud/examples/medieval/medieval.tscn lalu tekan F6 untuk melihat lembar karakter, tas, dan jurnal misi yang berfungsi. Tombol-tombolnya mengganti varian dan membuka rincian benda. Besi dan kulit Perkamen dan tinta Bingkai menu punya paku keling dan ornamen sudut kecil; HUD yang selalu terlihat mempertahankan tepi yang tenang. HP, mana, dan stamina memakai isian merah, biru, dan zaitun. Cinzel dibatasi pada judul dan subjudul; teks isi tetap memakai font induk/default. Font bawaannya menyertakan lisensinya di assets/fonts/cinzel/OFL.txt. Set ikon ukirannya menggambar ulang bag, book, box, coin, crown, flag, heart, key, map, potion, shield, star, sword, dan user, serta menambahkan scroll dan seal. Semua nama lainnya kembali ke set default, sehingga close dan settings mempertahankan gambar defaultnya di setiap preset. Cinzel mencakup aksara Latin; berikan font tersendiri untuk judul yang dilokalkan melalui shape.fonts. Apa yang diperiksa rangkaian uji untuk kedua varian. Skin abad pertengahan terpilih; panel menu dan HUD berupa bingkai tempaan, dengan ornamen hanya pada menu; judul memakai Cinzel sementara teks isi mempertahankan font warisan; ikon ukiran terimpor sebagai DPITexture; slot cepat sungguhan memakai skin tersebut; mengubah kenop pada salinan skin sampai ke slot tanpa menyentuh presetnya; dan beralih kembali memulihkan geometri default serta sci-fi.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # Atau: GoUi.use_preset(GoThemePresets.MEDIEVAL_LIGHT)",-1],[13,"make-a-kingdom-of-your-own","Bangun kerajaan Anda sendiri",1,"Tema JSON bisa mewarisi tema JSON lain. Nilai yang dihilangkan mempertahankan setelan induknya; pewarisan yang melingkar ditolak. Preset hasil generasi mempertahankan set ikon induknya. Setelan Efek shape.material 0: besi · 1: kulit · 2: perkamen. Menentukan guratan pada permukaannya. shape.grain_alpha Opasitas tekstur. Pakai 0 untuk permukaan yang bersih. shape.ornament_scale · shape.bevel_strength Ukuran ornamen sudut menu dan intensitas sorotan bevel. shape.fonts Memetakan peran title, subtitle, caption, body, dan button ke berkas font res:// yang ada di dalam add-on. Peran yang dihilangkan mempertahankan font warisannya. skin.dials Radius slot cepat, tampilnya paku keling, serat, dan sorotan. Tabel lengkap di bawah memuat setiap kenop.","python3 addons/gohud/tools/new_theme.py kingdom --from medieval_dark # Sunting themes/palettes/kingdom.json, lalu: python3 addons/gohud/tools/make_theme.py kingdom godot --headless --path . --import # Di GDScript, sebelum membuat widget-nya: GoUi.use_preset(&\"kingdom\")",76],[14,"colours","Warna",1,"Nama Dipakai untuk background Dasar layar surface · surface_soft · surface_high Tiga lapis panel — panel, kartu, sel yang terangkat border Garis tepi kartu dan tombol text · secondary · muted Tiga tingkat teks — isi, pendukung, diredupkan accent · on_accent Warna aksen dan teks yang diletakkan di atasnya success · warning · danger · info Warna teks status *_fill Status yang sama sebagai isian — bar dan bidang luas lainnya scrim · shadow · track Selubung di belakang popup, bayangan, dan alur bar Kenapa *_fill ada. Makna yang sama, tuntutan yang berlawanan. warning yang dipakai sebagai teks harus cukup gelap agar terbaca di atas latar terang; dipakai sebagai isian bar pengalaman ia harus cukup cerah agar terlihat. Satu token tidak bisa menjadi keduanya — bar pada tema terang berubah cokelat. Tema tanpa varian _fill otomatis kembali ke nama dasarnya, sehingga tema yang dibuat sebelum token ini ada tetap berjalan.","",-1],[14,"measurements-dp","Ukuran (dp)",1,"touch button_height gap_tiny gap_small gap gap_large padding padding_compact compact_padding_x compact_padding_y radius_small radius radius_large screen_margin scroll_deadzone scroll_edge scrollbar_width list_glyph icon_size notice_duration_ms","",-1],[14,"panel-opacity","Opasitas panel (%)",1,"panel_alpha card_alpha hud_alpha notice_alpha popup_alpha — seberapa pekat muka sebuah wadah. 80 secara default, sehingga game tetap terlihat di balik sebuah dialog; popup_alpha adalah 100. Tema tanpa token ini kembali ke 100 dan menggambar persis seperti sebelumnya. Baca nilai hasilnya sebagai rasio dengan GoUi.surface_alpha(variant); bagian Opasitas — game di balik panel memuat aturannya.","",-1],[14,"text-roles","Peran teks",1,"micro · compact · caption · body · button · subtitle · title — sebuah peran menamai satu ukuran, bukan satu tujuan. \"Teks terbesar\", bukan \"judul\". Dengan begitu skalanya tetap utuh walau sebuah layar memakainya untuk hal lain.","",-1],[14,"type-variations","Variasi tipe",1,"GoPanel GoCard GoButton GoPrimaryButton GoDangerButton GoDangerSolidButton GoBareButton GoCompactButton GoIconButton GoListButton GoTitleLabel GoSubtitleLabel GoCaptionLabel GoCompactLabel GoMicroLabel","",-1],[15,"five-layers-most-specific-first","Lima lapis, yang paling spesifik dulu",1,"Urutan Di mana Satuan Jangkauan ① argumen pada pemanggilan itu — surface.alpha, GoStyle.card(…, alpha) rasio 0.0–1.0 satu jendela ② GoConfig.container_alpha_overrides[kind] rasio 0.0–1.0 satu jenis panel, seluruh proyek ③ GoConfig.metric_overrides[<kind>_alpha] persen proyek yang menyimpan setiap ukuran di satu tempat ④ GoConfig.container_alpha rasio 0.0–1.0 semua panel sekaligus ⑤ GoHud/constants/<kind>_alpha milik temanya persen apa yang diputuskan tampilannya — sumber kebenarannya Tanpa satu pun dari itu disetel, nilainya 100, jadi tak ada yang berubah pada tema lama. Opasitas adalah rasio di mana-mana — kecuali di dalam temanya. Setiap kolom dan argumen alpha menerima 0.0–1.0, satuan yang sama dengan Color.a dan modulate.a, dan nilai negatif berarti \"tidak disetel\". Satu-satunya pengecualian adalah konstanta milik temanya, karena sebuah konstanta Theme tidak bisa memuat float: konstanta itu dan kanal yang menimpanya (metric_overrides, yang memakai nama dan tipe bilangan bulat yang sama dengan temanya) ditulis sebagai 80. Selain itu tidak ada.","# Satu jendela saja — dialog konfirmasi yang tak boleh menutupi pertarungan di belakangnya surface.alpha = 0.6 sheet.alpha = 0.7 dialogs.alpha = 0.9 # kolom @export pun rasio drawer.alpha = 0.7 GoPopover.open(slot, body, {\"alpha\": 0.9}) var glass := GoStyle.card(Color.TRANSPARENT, -1.0, -1.0, -1.0, 0.5) # Per jenis — jaga HUD tetap nyaris pekat, karena teksnya duduk langsung di atas dunianya GoUi.config.container_alpha_overrides = { GoTheme.BOX_PANEL: 0.7, # dialog dan lembar bisa bernapas GoTheme.BOX_HUD: 0.95, } GoUi.refresh() # menggambar ulang widget yang sudah terbuka # Seluruh proyek — dunia yang ramai ingin panelnya kembali pekat GoUi.config.container_alpha = 1.0 GoUi.refresh() GoUi.surface_alpha(GoTheme.BOX_PANEL) # rasio hasilnya, mis. 0.8",-1],[15,"what-follows-the-value-and-what-does-not","Apa yang mengikuti nilainya, dan apa yang tidak",1,"Mengikutinya — wadah Mengabaikannya — yang Anda tekan, dan penanda GoSurface (cangkang tunggal di balik dialog, lembar, dan dropdown) · GoSheet · GoDialogs · GoDrawer · GoPopover · GoNotice · GoSnackbar · GoPromptCard · GoCoachMark · GoConsole setiap tombol · GoSlot (slot cepat) · GoBadge · kontrol tersegmentasi · sel pilihan · chip · cakram dan avatar GoStyle.card() · hud_panel() · overlay_panel() · alert() · plate() · edge_card_panel() · style_notice_panel() · floating() · box() · surface() semua teks dan ikon Tombol yang statusnya pudar tak lagi mengatakan dirinya apa, dan lencana ada supaya dua huruf terbaca — keduanya bukan wadah, jadi keduanya tidak mengikuti nilai itu. Menu popup tetap pekat (popup_alpha 100). Mesin bisa menempatkan sebuah PopupMenu di dalam Window-nya sendiri, dan di sana OS tidak mengomposisinya dengan game: tembus pandangnya keluar hitam alih-alih tembus. Turunkan hanya pada proyek yang menyematkan subjendelanya (gui_embed_subwindows).","",-1],[15,"three-details-that-come-from-real-screens","Tiga rincian yang datang dari layar sungguhan",1,"Nilainya mengalikan, bukan menggantikan. Muka HUD default sudah beralfa 0.92, jadi hud_alpha 80 mendarat di 0.736 — tema yang sengaja membuat sebuah muka tembus pandang mempertahankan keputusan itu. Sisi sebaliknya: terapkan dua kali dan panelnya memudar dua kali, dan karena itulah alfanya dikalikan tepat di satu tempat (GoSkin.surface_box()) sementara setiap fungsi muka lain meneruskan argumennya alih-alih memudarkan hasilnya sendiri. Warna yang Anda berikan adalah warna yang Anda dapat. GoStyle.plate(…, fill) mempertahankan isian eksplisit persis seperti yang diberikan: Color(ink, 0.14) sudah menyatakan alfanya, dan mengalikan opasitas panel ke dalamnya akan memotong maksud pemanggilnya dua kali. GoStyle.floating(…, opaque = true) mengabaikan nilainya karena alasan sejenis — mengisi mukanya sampai pekat adalah seluruh tujuan flag itu. Panel yang bukan buatan gohud dapat aturan yang sama. GoStyle.fade_panel(node) — setelah node-nya ada di dalam tree, sehingga ia membaca tema yang diwarisinya. Ia idempoten: muka aslinya dicatat dan setiap pemanggilan menghitung ulang dari situ, jadi penggambaran ulang berkali-kali tak pernah menumpuk. Setelah menukar tema, GoStyle.forget_face(node) membuang catatan itu supaya pemanggilan berikutnya mengambil muka yang baru.","",-1],[15,"custom-faces-fade-too-and-that-is-the-part-that","Muka buatan sendiri pun memudar — dan di situlah bagian yang diam-diam rusak",1,"Panel bersudut potong (GoStyleBoxCut) dan bingkai tempaan (GoStyleBoxMedieval) bukan StyleBoxFlat; keduanya menggambar dirinya sendiri. Taruh opasitasnya hanya di cabang flat dan tema-tema ini diam-diam mengabaikannya sementara setiap uji berbasis nilai tetap lolos. Keduanya memudarkan latarnya dan mempertahankan pendar, paku keling, ukiran sudut, serta bevel pada kekuatan penuh — dan serat maupun bevel muka abad pertengahan memang selalu sebanding dengan alfa latarnya, jadi keduanya ikut menipis bersama panelnya. Dan itulah poin yang lebih luas: bg_color.a == 0.8 adalah sebuah angka. Dunianya tampak menembus dan teksnya tetap terbaca adalah persyaratannya. gohud memeriksa yang pertama di rangkaian uji headless-nya dan yang kedua dengan menggambar panel di atas garis-garis diagonal pada monitor virtual (tests/gohud_alpha_shot.gd) — pada muka flat, muka terpotong, dan muka tempaan, di tema gelap maupun di tema terang.","",-1],[16,"shapes-styleboxflat-cannot-make","Bentuk yang tak bisa dibuat StyleBoxFlat",1,"Kelas Apa yang digambarnya GoStyleBoxCut Sudut terpotong diagonal, satu tepi aksen yang ditebalkan, pendar di luar GoStyleBoxBracket Hanya penanda sudut, membiarkan kontennya tidak terkurung GoStyleBoxMedieval Bingkai tempaan — paku keling, ukiran sudut, sorotan bevel, dan serat besi, kulit, atau perkamen Ketiganya tersimpan ke dalam resource Theme seperti StyleBox mana pun — dan itulah yang membuat sebuah tema bisa mengubah bentuk. Berikan padding lewat content_margin_*. Menurunkan kelas StyleBox di GDScript berarti _get_style_margin() tidak pernah dipanggil (diukur pada Godot 4.7). Isi kolom bawaannya atau konten akan menempel pada garis tepinya.","",-1],[17,"what-you-can-change-on-one-page","Apa yang bisa Anda ubah — dalam satu halaman",1,"Di mana Apa Bagaimana from tema induk dark · light · scifi_dark · medieval_dark · … atau tema JSON lain. Kunci yang dihilangkan mewarisi nilainya; siklus pewarisan akan gagal palette background · tiga surface · border · tiga nada teks · accent · empat warna status · scrim · shadow · alur bar \"#RRGGBB\", alfa sebagai \"#RRGGBB@0.35\" warna cerah khusus isian *_vivid menjaga bar tetap pekat bahkan saat warna teksnya harus digelapkan — hilangkan satu dan pembangun tema akan memberi tahu keterbacaan tidak disetel manual. Teks, garis tepi, warna aksen, dan label di atasnya didorong oleh pembangun tema sampai melewati ambang batasnya — ubah aksennya saja dan pemeriksaannya tetap lolos shape kind flat (membulat) · cut (sudut terpotong) · medieval (bingkai tempaan) ukuran radius · radius_small · radius_large · gap · gap_small · gap_large · padding · button_height · button_padding[4] — token ikut menyesuaikan, sehingga panel dan perhitungan widget tidak pernah berselisih khusus cut cut_ratio · cut_max · corners (diagonal|all) · glow · edge khusus medieval material (0 besi · 1 kulit · 2 perkamen) · grain_alpha · ornament_scale · bevel_strength · fonts — title, subtitle, caption, body, button dipetakan ke berkas font res:// di dalam add-on skin base — keluarga untuk tempat-tempat yang digambar kode sendiri (joystick, slot, lencana, cincin coach mark, chip, pemisah) default · scifi · medieval dials — angka-angka dari tempat-tempat itu: lebar garis tepi dan rona slot, padding lencana, opasitas chip dan peringatan, lebar dan opasitas cincin joystick, ukuran chamfer sci-fi, pendar, dan kurung Setiap nilai induk dijabarkan di dalam JSON. Pembangun tema menuliskannya ke themes/skins/gohud_skin_<id>.tres — tidak ada kode skin yang disentuh. Hanya untuk mengubah gambarnya sendirilah Anda menjalankan --new-skin, yang menyiapkan kerangka subkelas GoSkin icons set ikon sebuah path res:// ke resource GoIconSet — dipertahankan dari induk JSON bila dihilangkan dark · title cara pemilih menampilkannya boolean · string","",-1],[17,"every-dial","Setiap kenop",1,"Tabel di bawah ini diisi oleh tools/make_site.py langsung dari baris @export pada skrip skin — tambahkan sebuah kenop atau ubah nilai defaultnya dan tabelnya ikut menyesuaikan. Pakai nama-nama ini di bawah skin.dials di dalam JSON. Kenop yang defaultnya tertulis 14 adalah integer, yang tertulis 10.0 adalah float — tulis bentuk mana pun di JSON dan pembangun tema akan mengonversinya ke tipe milik skrip. Skin default GoSkin — 17 Kenop Default Apa yang diaturnya chip_fill_alpha 0.16 Opasitas isian panel sebuah chip. chip_edge_alpha 0.45 Opasitas tepi panel sebuah chip. alert_tint 0.1 Seberapa jauh panel kotak peringatan dironai ke arah warna statusnya. slot_tint_lit 0.24 Rona aksen panel slot cepat selagi waktu jedanya berjalan. slot_tint_idle 0.08 Rona aksen panel slot cepat saat diam. slot_border_lit 2 Lebar garis tepi slot cepat (dp) selagi waktu jedanya berjalan. slot_border_idle 1 Lebar garis tepi slot cepat (dp) saat diam. badge_pad_x 5 Padding dalam horizontal (dp) sebuah lencana (jumlah, sisa waktu). badge_pad_y 1 Padding dalam vertikal (dp) sebuah lencana. badge_edge_alpha 0.6 Opasitas tepi panel sebuah lencana. float_shadow_alpha 0.45 Opasitas bayangan kartu mengambang (coach mark, kartu ajakan). float_shadow_size 14 Kaburnya bayangan (dp) kartu mengambang. float_shadow_lift 4 Pergeseran ke bawah (dp) bayangan sebuah kartu mengambang. float_glow_size 10.0 Jarak pendar (dp) panel mengambang yang berpendar alih-alih menjatuhkan bayangan, seperti panel bersudut potong sci-fi. joystick_base_alpha 0.42 Opasitas cakram dasar joystick. joystick_ring_alpha 0.45 Opasitas cincin joystick. joystick_ring_width 2.0 Lebar (dp) cincin joystick. Skin sci-fi GoSkinSciFi — 10 Kenop Default Apa yang diaturnya cut_chip 7.0 Ukuran chamfer (dp) panel sebuah chip. cut_skeleton 5.0 Ukuran chamfer (dp) panel kerangka pemuatan. cut_alert 8.0 Ukuran chamfer (dp) sebuah kotak peringatan. cut_segment 8.0 Ukuran chamfer (dp) sebuah kontrol tersegmentasi. cut_slot 6.0 Ukuran chamfer (dp) panel slot cepat. cut_disc_ratio 0.24 Chamfer avatar dan cakram = diameter × rasio ini. slot_glow_alpha 0.45 Opasitas pendar sebuah slot yang waktu jedanya sedang berjalan. slot_glow_size 6.0 Jarak pendar (dp) sebuah slot yang waktu jedanya sedang berjalan. bracket_arm 12.0 Panjang lengan (dp) kurung penanda sasaran pada coach mark. bracket_thickness 2.0 Ketebalan garis (dp) kurung penanda sasaran pada coach mark. Skin abad pertengahan GoSkinMedieval — 5 Kenop Default Apa yang diaturnya slot_radius 4.0 Radius sudut (dp) bingkai slot cepat abad pertengahan. leather_grain_alpha 0.035 Opasitas guratan kulit yang samar di dalam slot cepat. ornament_scale 1.0 Skala hiasan logam di sudut-sudut slot cepat. Bingkai menu memakai shape.ornament_scale. bevel_strength 0.18 Kekuatan sorotan logam di sepanjang tepi slot cepat. slot_rivets 1 Menampilkan paku keling logam kecil pada slot cepat: 0 menyembunyikannya, 1 menampilkannya.","",-1],[17,"subclass-the-skin-optional","Turunkan kelas skin (opsional)",1,"Hanya apa yang tak terjangkau tema dan bentuk — heksagon joystick, lencana slot, kurung penanda sasaran pada coach mark — yang tinggal di dalam sebuah skin. Turunkan GoSkin, timpa metode-metode itu saja, lalu arahkan kolom skin di JSON ke resource tersebut. Tema yang hanya mengubah warna melewatkan langkah ini. Sebuah pemeriksaan menjaga janji itu. tools/check_scaffold.sh membuat tema sekali pakai pada setiap jalan uji — mengubah aksennya, menyetel radiusnya ke 4 — lalu memverifikasi generasi, perambatan token, dan kelulusan kontras sebelum menghapusnya. Jalan uji pertama menemukan sebuah tema yang hanya diubah aksennya gagal pada 8 pasangan: pembangun tema mendorong warna teks tetapi memakai aksennya apa adanya. Kini ia mendorong aksen dan label di atasnya juga.","",-1],[18,"same-hue-text-on-a-same-hue-tint","Teks berwarna senada di atas rona senada",1,"Jebakan ini muncul tiga kali di basis kode ini — tombol yang ditekan (panel aksen, label aksen), tombol bahaya, dan chip. Ia tampak bagus sebagai contoh warna lalu ambruk begitu diukur, karena keduanya berbagi rona yang sama sehingga tidak ada beda terang di antaranya. Karena itu warna label tidak dipilih dengan tangan. Pembangun tema dan GoSkin masing-masing mendorong terangnya — dan hanya terangnya — sampai ambang batasnya terlewati pada panel tempat teks itu benar-benar berada. Rona dan kepekatannya bertahan, sehingga paletnya menjaga wataknya dan mengubahnya tetap menjaga kontrasnya.","",-1],[18,"colour-read-as-text-and-colour-painted-as-area-w","Warna yang dibaca sebagai teks dan warna yang dilukis sebagai bidang menuntut hal yang berlawanan",1,"Pada tema terang, warna peringatan harus digelapkan agar tetap terbaca sebagai teks (#96500A). Ketika isian bar mewarisi warna itu, bar pengalaman berubah cokelat. Warna saja tak bisa memperbaikinya: kuning memang cerah secara hakiki, jadi ia melewati 3:1 bahkan tanpa alur abu-abu sama sekali, dan menggelapkan alurnya justru membuatnya lebih buruk (1,52 → 1,06). Maka keduanya dipisahkan. Warnanya tetap cerah — paletnya membawa warna khusus isian seperti warning_vivid. Tepinya yang membawa kontras — GoSkin menggambar garis tepi 1dp pada isian mana pun yang tak bisa mencapai 3:1 terhadap alurnya, sehingga \"seberapa penuh isinya\" tetap terbaca. Melewatkannya akan dilaporkan. Tanpa sebuah *_vivid, isian yang keluar gelap membuat pembangun tema mencetak the bar looks drab — add warning_vivid to the palette (bar-nya kusam — tambahkan warning_vivid ke paletnya). Tempat yang dulu memburuk diam-diam kini bersuara.","MY_LIGHT = dict( warning=hexc(\"9A5407\"), # dibaca sebagai teks warning_vivid=hexc(\"F2A007\"), # dilukis pada bar )",-1],[18,"a-floating-panel-cannot-know-what-is-behind-it","Panel mengambang tak bisa tahu apa yang ada di belakangnya",1,"Sebuah HUD digambar di atas game — padang salju, atau sebuah gua. Kalau panelnya tembus pandang, apa pun yang ada di belakangnya akan merembes dan mengubah warna panelnya, sekaligus menyeret turun kontras teksnya. Pada opasitas 82%, teks muted tema gelap jatuh ke 3,74:1 di atas latar yang cerah — di bawah ambang minimum. Maka panel tembus pandang diukur dengan putih murni dan hitam murni di belakangnya; itulah yang terburuk yang bisa disodorkan sebuah adegan game. Panel HUD tema bawaan cukup pekat untuk lolos (92%) sambil mempertahankan kesan kacanya. Karena alasan yang sama, warna ikon pun tidak dipatok. Glif slot cepat dahulu dipatok putih dan terukur 1,11:1 pada tema terang — kini ia mengikuti panel tempatnya berada, persis seperti labelnya. Dua pemeriksa, dua jangkauan. check_contrast.py membaca berkas temanya; warna yang dicampur sebuah skin saat berjalan (chip, slot) diukur oleh bagian skin contrast pada rangkaian uji di dalam Godot.","",-1]]};
